-- Tranquil Rest PMS: complete database setup for a NEW Supabase project.
-- Paste into Supabase → SQL Editor → Run. Generated by scripts/build-setup-sql.sh; do not edit by hand.
-- Contents: 20261123000001_init.sql 20261123000002_booking_rpcs.sql 20261123000003_backup_export.sql 20261123000004_restore_backup.sql 20261123000005_audit_staff.sql 20261123000006_new_accounts_inactive.sql + seed.sql

-- ============================================================================
-- 20261123000001_init.sql
-- ============================================================================
-- =============================================================================
-- Tranquil Rest PMS — initial schema
-- Postgres 15+ / Supabase. All times are timestamptz; the business runs on
-- Asia/Colombo (UTC+05:30, no DST).
-- =============================================================================

create extension if not exists btree_gist;
create extension if not exists pgcrypto;

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
create type public.app_role        as enum ('admin', 'caretaker');
create type public.room_category   as enum ('non_ac', 'ac');
create type public.booking_type    as enum ('short_time', 'day', 'night', 'full_day');
create type public.booking_status  as enum ('booked', 'checked_in', 'checked_out', 'cancelled');
create type public.housekeeping    as enum ('ready', 'cleaning');
create type public.payment_method  as enum ('cash', 'bank');
create type public.payment_kind    as enum ('advance', 'balance');
create type public.expense_type    as enum ('fixed', 'variable');

-- -----------------------------------------------------------------------------
-- Profiles (one row per auth user)
-- -----------------------------------------------------------------------------
create table public.profiles (
  id            uuid primary key references auth.users (id) on delete cascade,
  role          public.app_role not null default 'caretaker',
  display_name  text not null default 'Caretaker',
  -- bcrypt hash of the 4-digit device-unlock PIN (caretakers only)
  pin_hash      text,
  active        boolean not null default true,
  created_at    timestamptz not null default now()
);

-- Helpers used by RLS. SECURITY DEFINER so they can read profiles regardless
-- of the caller's own policies; search_path pinned to avoid hijacking.
create or replace function public.current_role_name()
returns public.app_role
language sql stable security definer set search_path = public
as $$
  select role from public.profiles where id = auth.uid() and active
$$;

create or replace function public.is_admin()
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce((select role = 'admin' from public.profiles where id = auth.uid() and active), false)
$$;

create or replace function public.is_staff()
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.profiles where id = auth.uid() and active)
$$;

-- -----------------------------------------------------------------------------
-- Settings (single row)
-- -----------------------------------------------------------------------------
create table public.settings (
  id                       smallint primary key default 1 check (id = 1),
  property_name            text not null default 'Tranquil Rest',
  property_phone           text,
  cleaning_buffer_minutes  integer not null default 30 check (cleaning_buffer_minutes between 0 and 240),
  updated_at               timestamptz not null default now(),
  updated_by               uuid references auth.users (id)
);
insert into public.settings (id) values (1);

-- -----------------------------------------------------------------------------
-- Rooms & pricing (no hard-coded prices anywhere in the app)
-- -----------------------------------------------------------------------------
create table public.rooms (
  id            uuid primary key default gen_random_uuid(),
  room_number   integer not null unique,
  name          text not null,              -- e.g. 'Room 1'
  name_si       text not null,              -- e.g. 'කාමර 1'
  category      public.room_category not null default 'non_ac',
  housekeeping  public.housekeeping not null default 'ready',
  active        boolean not null default true,
  updated_at    timestamptz not null default now(),
  updated_by    uuid references auth.users (id)
);

create table public.pricing_rules (
  id                  uuid primary key default gen_random_uuid(),
  category            public.room_category not null,
  booking_type        public.booking_type not null,
  price               numeric(10,2) not null check (price >= 0),
  -- Fixed-window types (day/night) use start/end; duration types use minutes.
  default_start_time  time,
  default_end_time    time,
  duration_minutes    integer check (duration_minutes > 0),
  updated_at          timestamptz not null default now(),
  updated_by          uuid references auth.users (id),
  unique (category, booking_type),
  check (duration_minutes is not null or (default_start_time is not null and default_end_time is not null))
);

-- -----------------------------------------------------------------------------
-- Bookings
-- -----------------------------------------------------------------------------
create table public.bookings (
  id                   uuid primary key default gen_random_uuid(),
  room_id              uuid not null references public.rooms (id),
  booking_type         public.booking_type not null,
  guest_name           text,
  guest_phone          text not null check (length(regexp_replace(guest_phone, '\D', '', 'g')) between 9 and 12),
  check_in_time        timestamptz not null,
  check_out_time       timestamptz not null,
  room_charge          numeric(10,2) not null check (room_charge >= 0),
  status               public.booking_status not null default 'booked',
  notes                text,
  actual_check_in_at   timestamptz,
  actual_check_out_at  timestamptz,
  cancelled_at         timestamptz,
  cancelled_by         uuid references auth.users (id),
  cancel_reason        text,
  created_at           timestamptz not null default now(),
  created_by           uuid references auth.users (id) default auth.uid(),
  updated_at           timestamptz not null default now(),
  updated_by           uuid references auth.users (id) default auth.uid(),
  check (check_out_time > check_in_time),
  -- Hard guarantee against double-booking: NewStart < ExistingEnd AND NewEnd > ExistingStart
  -- ('[)' range semantics) for every non-cancelled booking in the same room.
  constraint bookings_no_overlap exclude using gist (
    room_id with =,
    tstzrange(check_in_time, check_out_time, '[)') with &&
  ) where (status <> 'cancelled')
);
create index bookings_time_idx on public.bookings (check_in_time, check_out_time);
create index bookings_room_idx on public.bookings (room_id, check_in_time);

create table public.payments (
  id          uuid primary key default gen_random_uuid(),
  booking_id  uuid not null references public.bookings (id),
  kind        public.payment_kind not null,
  method      public.payment_method not null,
  amount      numeric(10,2) not null check (amount > 0),
  paid_at     timestamptz not null default now(),
  created_at  timestamptz not null default now(),
  created_by  uuid references auth.users (id) default auth.uid()
);
create index payments_paid_at_idx on public.payments (paid_at);
create index payments_booking_idx on public.payments (booking_id);

create table public.addon_presets (
  id          uuid primary key default gen_random_uuid(),
  label_si    text not null,
  label_en    text not null,
  price       numeric(10,2) not null check (price >= 0),
  sort_order  integer not null default 0,
  active      boolean not null default true
);

create table public.booking_addons (
  id          uuid primary key default gen_random_uuid(),
  booking_id  uuid not null references public.bookings (id),
  label       text not null,
  unit_price  numeric(10,2) not null check (unit_price >= 0),
  quantity    integer not null default 1 check (quantity > 0),
  amount      numeric(10,2) generated always as (unit_price * quantity) stored,
  created_at  timestamptz not null default now(),
  created_by  uuid references auth.users (id) default auth.uid()
);
create index booking_addons_booking_idx on public.booking_addons (booking_id);

-- -----------------------------------------------------------------------------
-- Expenses (admin only)
-- -----------------------------------------------------------------------------
create table public.expenses (
  id            uuid primary key default gen_random_uuid(),
  expense_type  public.expense_type not null,
  category      text not null,
  amount        numeric(10,2) not null check (amount > 0),
  expense_date  date not null,
  note          text,
  created_at    timestamptz not null default now(),
  created_by    uuid references auth.users (id) default auth.uid()
);
create index expenses_date_idx on public.expenses (expense_date);

-- -----------------------------------------------------------------------------
-- Audit log
-- -----------------------------------------------------------------------------
create table public.audit_logs (
  id          bigint generated always as identity primary key,
  table_name  text not null,
  record_id   uuid,
  action      text not null,          -- insert | update | cancel | check_in | check_out | delete
  actor_id    uuid,
  actor_name  text,
  old_data    jsonb,
  new_data    jsonb,
  created_at  timestamptz not null default now()
);
create index audit_logs_created_idx on public.audit_logs (created_at desc);
create index audit_logs_record_idx on public.audit_logs (record_id);

create or replace function public.tg_audit()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_action text := lower(tg_op);
  v_id     uuid;
  v_name   text;
begin
  -- Nested IF: plpgsql resolves NEW.status eagerly, which fails on other tables.
  if tg_op = 'UPDATE' and tg_table_name = 'bookings' then
    if (to_jsonb(new) ->> 'status') is distinct from (to_jsonb(old) ->> 'status') then
      v_action := case to_jsonb(new) ->> 'status'
        when 'cancelled'   then 'cancel'
        when 'checked_in'  then 'check_in'
        when 'checked_out' then 'check_out'
        else 'update' end;
    end if;
  end if;

  v_id := case when tg_op = 'DELETE' then (to_jsonb(old) ->> 'id')::uuid
               else (to_jsonb(new) ->> 'id')::uuid end;
  select display_name into v_name from public.profiles where id = auth.uid();

  insert into public.audit_logs (table_name, record_id, action, actor_id, actor_name, old_data, new_data)
  values (
    tg_table_name, v_id, v_action, auth.uid(), coalesce(v_name, 'system'),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end
  );
  return coalesce(new, old);
end $$;

create or replace function public.tg_touch()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  if auth.uid() is not null then
    new.updated_by := auth.uid();
  end if;
  return new;
end $$;

-- Caretakers must never re-open a cancelled booking or reprice after the fact
-- beyond what the UI allows; this guard keeps state transitions sane for everyone.
create or replace function public.tg_booking_guard()
returns trigger
language plpgsql
as $$
begin
  if old.status = 'cancelled' and new.status <> 'cancelled' and not public.is_admin() then
    raise exception 'Cancelled bookings can only be restored by an admin';
  end if;
  if old.status = 'checked_out' and new.status in ('booked','checked_in') and not public.is_admin() then
    raise exception 'Checked-out bookings can only be reopened by an admin';
  end if;
  if new.status = 'cancelled' and old.status <> 'cancelled' then
    new.cancelled_at := coalesce(new.cancelled_at, now());
    new.cancelled_by := coalesce(new.cancelled_by, auth.uid());
  end if;
  return new;
end $$;

create trigger bookings_touch  before update on public.bookings      for each row execute function public.tg_touch();
create trigger bookings_guard  before update on public.bookings      for each row execute function public.tg_booking_guard();
create trigger rooms_touch     before update on public.rooms         for each row execute function public.tg_touch();
create trigger pricing_touch   before update on public.pricing_rules for each row execute function public.tg_touch();
create trigger settings_touch  before update on public.settings      for each row execute function public.tg_touch();

create trigger audit_bookings       after insert or update or delete on public.bookings       for each row execute function public.tg_audit();
create trigger audit_payments       after insert or update or delete on public.payments       for each row execute function public.tg_audit();
create trigger audit_booking_addons after insert or update or delete on public.booking_addons for each row execute function public.tg_audit();
create trigger audit_expenses       after insert or update or delete on public.expenses       for each row execute function public.tg_audit();
create trigger audit_rooms          after insert or update or delete on public.rooms          for each row execute function public.tg_audit();
create trigger audit_pricing        after insert or update or delete on public.pricing_rules  for each row execute function public.tg_audit();
create trigger audit_settings       after update on public.settings                           for each row execute function public.tg_audit();
create trigger audit_addon_presets  after insert or update or delete on public.addon_presets  for each row execute function public.tg_audit();

-- -----------------------------------------------------------------------------
-- RPCs
-- -----------------------------------------------------------------------------

-- Returns hard conflicts (overlap) and soft warnings (inside the cleaning buffer)
-- for a proposed slot. The exclusion constraint is the real guard; this exists
-- so the UI can explain *why* a slot is not available before saving.
create or replace function public.check_booking_slot(
  p_room_id uuid, p_start timestamptz, p_end timestamptz, p_exclude uuid default null
)
returns table (booking_id uuid, kind text, check_in_time timestamptz, check_out_time timestamptz, guest_name text)
language sql stable security invoker set search_path = public
as $$
  with buf as (
    select make_interval(mins => cleaning_buffer_minutes) as b from public.settings where id = 1
  )
  select b.id,
         case when p_start < b.check_out_time and p_end > b.check_in_time then 'overlap' else 'buffer' end,
         b.check_in_time, b.check_out_time, b.guest_name
  from public.bookings b, buf
  where b.room_id = p_room_id
    and b.status <> 'cancelled'
    and (p_exclude is null or b.id <> p_exclude)
    and p_start < b.check_out_time + buf.b
    and p_end   > b.check_in_time  - buf.b
  order by b.check_in_time
$$;

-- Caretakers may flip housekeeping state but not edit other room columns.
create or replace function public.set_room_housekeeping(p_room_id uuid, p_state public.housekeeping)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not public.is_staff() then
    raise exception 'Not allowed';
  end if;
  update public.rooms set housekeeping = p_state where id = p_room_id;
end $$;

-- Verify the device-unlock PIN of the signed-in caretaker.
create or replace function public.verify_pin(p_pin text)
returns boolean
language sql stable security definer set search_path = public, extensions
as $$
  select coalesce(
    (select pin_hash is not null and pin_hash = crypt(p_pin, pin_hash)
       from public.profiles where id = auth.uid() and active),
    false)
$$;

-- Admin sets a staff member's PIN (stored as bcrypt).
create or replace function public.set_staff_pin(p_user_id uuid, p_pin text)
returns void
language plpgsql security definer set search_path = public, extensions
as $$
begin
  if not public.is_admin() then
    raise exception 'Only admins can set PINs';
  end if;
  if p_pin !~ '^\d{4}$' then
    raise exception 'PIN must be exactly 4 digits';
  end if;
  update public.profiles set pin_hash = crypt(p_pin, gen_salt('bf')) where id = p_user_id;
end $$;

-- Create a profile row automatically for every new auth user (caretaker by default).
create or replace function public.handle_new_user()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1)))
  on conflict (id) do nothing;
  return new;
end $$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- -----------------------------------------------------------------------------
-- Row Level Security
-- -----------------------------------------------------------------------------
alter table public.profiles       enable row level security;
alter table public.settings       enable row level security;
alter table public.rooms          enable row level security;
alter table public.pricing_rules  enable row level security;
alter table public.bookings       enable row level security;
alter table public.payments       enable row level security;
alter table public.addon_presets  enable row level security;
alter table public.booking_addons enable row level security;
alter table public.expenses       enable row level security;
alter table public.audit_logs     enable row level security;

-- profiles: see yourself; admins see/manage everyone. pin_hash is never selectable
-- by clients (column privilege below).
create policy profiles_select on public.profiles for select to authenticated
  using (id = auth.uid() or public.is_admin());
create policy profiles_admin_update on public.profiles for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- settings / rooms / pricing / presets: all staff read; admin writes.
create policy settings_select on public.settings for select to authenticated using (public.is_staff());
create policy settings_update on public.settings for update to authenticated using (public.is_admin()) with check (public.is_admin());

create policy rooms_select on public.rooms for select to authenticated using (public.is_staff());
create policy rooms_admin_all on public.rooms for all to authenticated using (public.is_admin()) with check (public.is_admin());

create policy pricing_select on public.pricing_rules for select to authenticated using (public.is_staff());
create policy pricing_admin_all on public.pricing_rules for all to authenticated using (public.is_admin()) with check (public.is_admin());

create policy presets_select on public.addon_presets for select to authenticated using (public.is_staff());
create policy presets_admin_all on public.addon_presets for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- bookings: caretakers see the operational window only (active bookings plus the
-- last 2 days), so they cannot reconstruct monthly sales. No DELETE policy for
-- anyone: bookings are soft-deleted via status = 'cancelled'.
create policy bookings_select on public.bookings for select to authenticated
  using (
    public.is_admin()
    or (public.is_staff() and (status in ('booked','checked_in') or check_out_time >= now() - interval '2 days'
                               or updated_at >= now() - interval '2 days'))
  );
create policy bookings_insert on public.bookings for insert to authenticated
  with check (public.is_staff() and created_by = auth.uid());
create policy bookings_update on public.bookings for update to authenticated
  using (public.is_staff()) with check (public.is_staff());

-- payments & add-ons: staff read (scoped through visible bookings) and add;
-- only admins correct or remove them.
create policy payments_select on public.payments for select to authenticated
  using (public.is_admin() or exists (select 1 from public.bookings b where b.id = booking_id));
create policy payments_insert on public.payments for insert to authenticated
  with check (public.is_staff() and created_by = auth.uid());
create policy payments_admin_update on public.payments for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy payments_admin_delete on public.payments for delete to authenticated using (public.is_admin());

create policy addons_select on public.booking_addons for select to authenticated
  using (public.is_admin() or exists (select 1 from public.bookings b where b.id = booking_id));
create policy addons_insert on public.booking_addons for insert to authenticated
  with check (public.is_staff() and created_by = auth.uid());
create policy addons_admin_update on public.booking_addons for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy addons_admin_delete on public.booking_addons for delete to authenticated using (public.is_admin());

-- expenses & audit: admin only. Audit rows are written by the SECURITY DEFINER
-- trigger, never directly by clients.
create policy expenses_admin_all on public.expenses for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy audit_admin_select on public.audit_logs for select to authenticated using (public.is_admin());

-- Column privileges
revoke all on public.profiles from anon, authenticated;
grant select (id, role, display_name, active, created_at) on public.profiles to authenticated;
grant update (role, display_name, active) on public.profiles to authenticated;

revoke all on public.audit_logs from anon, authenticated;
grant select on public.audit_logs to authenticated;

revoke all on all tables in schema public from anon;
revoke execute on all functions in schema public from anon, public;
grant execute on function public.is_admin(), public.is_staff(), public.current_role_name(),
  public.check_booking_slot(uuid, timestamptz, timestamptz, uuid),
  public.set_room_housekeeping(uuid, public.housekeeping),
  public.verify_pin(text), public.set_staff_pin(uuid, text)
  to authenticated;

-- -----------------------------------------------------------------------------
-- Realtime: push changes to every open device
-- -----------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.bookings, public.rooms, public.payments, public.booking_addons;
  end if;
end $$;

-- ============================================================================
-- 20261123000002_booking_rpcs.sql
-- ============================================================================
-- Atomic booking operations. SECURITY INVOKER: RLS still applies to the caller.

-- Creates a booking with its advance payment and add-ons in one transaction.
create or replace function public.create_booking(p_booking jsonb, p_advance jsonb default null, p_addons jsonb default '[]'::jsonb)
returns uuid
language plpgsql security invoker set search_path = public
as $$
declare
  v_id uuid;
  v_status public.booking_status := coalesce((p_booking ->> 'status')::public.booking_status, 'booked');
begin
  if v_status not in ('booked', 'checked_in') then
    raise exception 'New bookings must be booked or checked_in';
  end if;

  insert into public.bookings (room_id, booking_type, guest_name, guest_phone, check_in_time, check_out_time,
                               room_charge, status, notes, actual_check_in_at)
  values (
    (p_booking ->> 'room_id')::uuid,
    (p_booking ->> 'booking_type')::public.booking_type,
    nullif(trim(p_booking ->> 'guest_name'), ''),
    p_booking ->> 'guest_phone',
    (p_booking ->> 'check_in_time')::timestamptz,
    (p_booking ->> 'check_out_time')::timestamptz,
    (p_booking ->> 'room_charge')::numeric,
    v_status,
    nullif(trim(p_booking ->> 'notes'), ''),
    case when v_status = 'checked_in' then now() end
  )
  returning id into v_id;

  if p_advance is not null and coalesce((p_advance ->> 'amount')::numeric, 0) > 0 then
    insert into public.payments (booking_id, kind, method, amount)
    values (v_id, coalesce((p_advance ->> 'kind')::public.payment_kind, 'advance'),
            (p_advance ->> 'method')::public.payment_method, (p_advance ->> 'amount')::numeric);
  end if;

  insert into public.booking_addons (booking_id, label, unit_price, quantity)
  select v_id, a ->> 'label', (a ->> 'unit_price')::numeric, coalesce((a ->> 'quantity')::int, 1)
  from jsonb_array_elements(coalesce(p_addons, '[]'::jsonb)) a;

  if v_status = 'checked_in' then
    perform public.set_room_housekeeping((p_booking ->> 'room_id')::uuid, 'ready');
  end if;

  return v_id;
end $$;

-- Checks a guest out: records the real time, frees the rest of the slot if they
-- leave early, and sends the room to cleaning.
create or replace function public.checkout_booking(p_booking_id uuid)
returns void
language plpgsql security invoker set search_path = public
as $$
declare
  v_room uuid;
begin
  update public.bookings
     set status = 'checked_out',
         actual_check_out_at = now(),
         check_out_time = greatest(check_in_time + interval '1 minute', least(check_out_time, now()))
   where id = p_booking_id and status = 'checked_in'
  returning room_id into v_room;

  if v_room is null then
    raise exception 'Booking is not checked in';
  end if;
  perform public.set_room_housekeeping(v_room, 'cleaning');
end $$;

revoke execute on function public.create_booking(jsonb, jsonb, jsonb), public.checkout_booking(uuid) from public, anon;
grant execute on function public.create_booking(jsonb, jsonb, jsonb), public.checkout_booking(uuid) to authenticated;

-- ============================================================================
-- 20261123000003_backup_export.sql
-- ============================================================================
-- Read-only export for the nightly Google Sheets / Drive backup.
-- The backup script authenticates with a random "backup key" (not the
-- service_role key), so a leaked key can only READ data, never change it.

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

create table if not exists private.backup_keys (
  id          smallint primary key default 1 check (id = 1),
  key_hash    text not null,
  created_at  timestamptz not null default now(),
  created_by  uuid,
  last_used   timestamptz
);

-- Admin generates (or rotates) the key. The plain key is returned ONCE; only a hash is stored.
create or replace function public.rotate_backup_key()
returns text
language plpgsql security definer set search_path = public, private, extensions
as $$
declare
  v_key text := encode(gen_random_bytes(24), 'hex');
begin
  if not public.is_admin() then
    raise exception 'Only admins can create a backup key';
  end if;
  insert into private.backup_keys (id, key_hash, created_by)
  values (1, encode(digest(v_key, 'sha256'), 'hex'), auth.uid())
  on conflict (id) do update set key_hash = excluded.key_hash, created_at = now(), created_by = excluded.created_by, last_used = null;
  insert into public.audit_logs (table_name, action, actor_id, actor_name)
  values ('backup_keys', 'rotate', auth.uid(), (select display_name from public.profiles where id = auth.uid()));
  return v_key;
end $$;

create or replace function public.backup_key_status()
returns table (created_at timestamptz, last_used timestamptz)
language sql stable security definer set search_path = public, private
as $$
  select created_at, last_used from private.backup_keys where id = 1 and public.is_admin()
$$;

-- Full snapshot of every business table as one JSON document.
-- PIN hashes are deliberately excluded.
create or replace function public.export_backup(p_key text)
returns jsonb
language plpgsql volatile security definer set search_path = public, private, extensions
as $$
declare
  v_ok boolean;
begin
  select coalesce(key_hash = encode(digest(coalesce(p_key, ''), 'sha256'), 'hex'), false)
    into v_ok from private.backup_keys where id = 1;
  if not coalesce(v_ok, false) then
    perform pg_sleep(1); -- slow down guessing
    raise exception 'Invalid backup key' using errcode = '28000';
  end if;
  update private.backup_keys set last_used = now() where id = 1;

  return jsonb_build_object(
    'format',         'tranquil-rest-backup/1',
    'exported_at',    now(),
    'settings',       (select to_jsonb(s) from public.settings s where id = 1),
    'rooms',          coalesce((select jsonb_agg(to_jsonb(r) order by r.room_number) from public.rooms r), '[]'),
    'pricing_rules',  coalesce((select jsonb_agg(to_jsonb(p) order by p.category, p.booking_type) from public.pricing_rules p), '[]'),
    'addon_presets',  coalesce((select jsonb_agg(to_jsonb(a) order by a.sort_order) from public.addon_presets a), '[]'),
    'profiles',       coalesce((select jsonb_agg(jsonb_build_object('id', id, 'role', role, 'display_name', display_name, 'active', active, 'created_at', created_at)) from public.profiles), '[]'),
    'bookings',       coalesce((select jsonb_agg(to_jsonb(b) order by b.check_in_time) from public.bookings b), '[]'),
    'payments',       coalesce((select jsonb_agg(to_jsonb(p) order by p.paid_at) from public.payments p), '[]'),
    'booking_addons', coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at) from public.booking_addons a), '[]'),
    'expenses',       coalesce((select jsonb_agg(to_jsonb(e) order by e.expense_date) from public.expenses e), '[]'),
    'audit_logs',     coalesce((select jsonb_agg(to_jsonb(l) order by l.id) from public.audit_logs l), '[]')
  );
end $$;

revoke execute on function public.rotate_backup_key(), public.backup_key_status(), public.export_backup(text) from public, anon, authenticated;
grant execute on function public.rotate_backup_key(), public.backup_key_status() to authenticated;
-- The backup script calls with the anon (public) API key + the backup key.
grant execute on function public.export_backup(text) to anon, authenticated;

-- ============================================================================
-- 20261123000004_restore_backup.sql
-- ============================================================================
-- Restore from a nightly backup file (format tranquil-rest-backup/1).
--
--   restore_backup(backup, 'merge',   dry_run)  → put back rows that are missing; never overwrites or deletes.
--   restore_backup(backup, 'replace', dry_run, 'REPLACE ALL DATA')
--                                               → wipe business data and load the backup exactly.
--
-- Everything runs in one transaction: it either fully succeeds or changes nothing.
-- With dry_run = true the work is done and then rolled back, returning the same report.
-- Callable by admins (app) or the service_role (CLI / SQL editor).

-- Shared snapshot builder (used by the keyed nightly export and the admin download).
create or replace function private.snapshot()
returns jsonb
language sql stable security definer set search_path = public, private
as $$
  select jsonb_build_object(
    'format',         'tranquil-rest-backup/1',
    'exported_at',    now(),
    'settings',       (select to_jsonb(s) from public.settings s where id = 1),
    'rooms',          coalesce((select jsonb_agg(to_jsonb(r) order by r.room_number) from public.rooms r), '[]'),
    'pricing_rules',  coalesce((select jsonb_agg(to_jsonb(p) order by p.category, p.booking_type) from public.pricing_rules p), '[]'),
    'addon_presets',  coalesce((select jsonb_agg(to_jsonb(a) order by a.sort_order) from public.addon_presets a), '[]'),
    'profiles',       coalesce((select jsonb_agg(jsonb_build_object('id', id, 'role', role, 'display_name', display_name, 'active', active, 'created_at', created_at)) from public.profiles), '[]'),
    'bookings',       coalesce((select jsonb_agg(to_jsonb(b) order by b.check_in_time) from public.bookings b), '[]'),
    'payments',       coalesce((select jsonb_agg(to_jsonb(p) order by p.paid_at) from public.payments p), '[]'),
    'booking_addons', coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at) from public.booking_addons a), '[]'),
    'expenses',       coalesce((select jsonb_agg(to_jsonb(e) order by e.expense_date) from public.expenses e), '[]'),
    'audit_logs',     coalesce((select jsonb_agg(to_jsonb(l) order by l.id) from public.audit_logs l), '[]')
  )
$$;

create or replace function public.export_backup(p_key text)
returns jsonb
language plpgsql volatile security definer set search_path = public, private, extensions
as $$
declare
  v_ok boolean;
begin
  select coalesce(key_hash = encode(digest(coalesce(p_key, ''), 'sha256'), 'hex'), false)
    into v_ok from private.backup_keys where id = 1;
  if not coalesce(v_ok, false) then
    perform pg_sleep(1);
    raise exception 'Invalid backup key' using errcode = '28000';
  end if;
  update private.backup_keys set last_used = now() where id = 1;
  return private.snapshot();
end $$;

-- Admins can download the current data at any time (used as a safety copy before a restore).
create or replace function public.export_backup_admin()
returns jsonb
language plpgsql stable security definer set search_path = public, private
as $$
begin
  if not coalesce(public.is_admin() or private.is_trusted_backend(), false) then
    raise exception 'Only admins can export data';
  end if;
  return private.snapshot();
end $$;

-- Loads one table's rows from the backup. Returns {restored, skipped}.
-- User references (created_by etc.) pointing at accounts that don't exist in this
-- project are set to NULL rather than failing, so a backup can move to a new project.
create or replace function private.restore_table(p_table text, p_rows jsonb, p_mode text)
returns jsonb
language plpgsql security definer set search_path = public, private
as $$
declare
  v_cols text;
  v_ref text;
  v_overriding text := case when p_table = 'audit_logs' then 'overriding system value' else '' end;
  v_conflict text := case when p_mode = 'merge' then 'on conflict do nothing' else '' end;
  v_before bigint;
  v_after bigint;
  v_total int := coalesce(jsonb_array_length(p_rows), 0);
  v_row record;
  v_skipped int := 0;
begin
  if v_total = 0 then
    return jsonb_build_object('restored', 0, 'skipped', 0);
  end if;

  execute format('drop table if exists pg_temp.%I', 'r_' || p_table);
  execute format('create temp table %I (like public.%I) on commit drop', 'r_' || p_table, p_table);
  execute format('insert into %1$I select * from jsonb_populate_recordset(null::%1$I, $1)', 'r_' || p_table) using p_rows;

  for v_ref in
    select column_name from information_schema.columns
    where table_schema = 'public' and table_name = p_table
      and column_name in ('created_by', 'updated_by', 'cancelled_by', 'actor_id')
  loop
    -- actor_id in audit_logs is informational (no FK) and kept as-is
    continue when v_ref = 'actor_id';
    execute format('update %1$I set %2$I = null where %2$I is not null and not exists (select 1 from auth.users u where u.id = %1$I.%2$I)',
                   'r_' || p_table, v_ref);
  end loop;

  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols
  from information_schema.columns
  where table_schema = 'public' and table_name = p_table and is_generated = 'NEVER';

  execute format('select count(*) from public.%I', p_table) into v_before;

  if p_mode = 'merge' and p_table in ('bookings', 'payments', 'booking_addons', 'rooms') then
    -- Row by row so one clash (overlapping booking, duplicate room number, missing
    -- parent booking) skips that row instead of aborting the whole merge.
    for v_row in execute format('select id::text as id from %I', 'r_' || p_table) loop
      begin
        execute format('insert into public.%1$I (%2$s) select %2$s from %3$I where id::text = $1 on conflict (id) do nothing',
                       p_table, v_cols, 'r_' || p_table) using v_row.id;
      exception when exclusion_violation or unique_violation or foreign_key_violation or check_violation then
        v_skipped := v_skipped + 1;
      end;
    end loop;
  else
    execute format('insert into public.%1$I (%2$s) %4$s select %2$s from %3$I %5$s',
                   p_table, v_cols, 'r_' || p_table, v_overriding, v_conflict);
  end if;

  execute format('select count(*) from public.%I', p_table) into v_after;
  return jsonb_build_object('restored', v_after - v_before, 'skipped', v_total - (v_after - v_before));
end $$;

-- True for the Supabase service_role (CLI) or a direct database session such as the
-- SQL editor. NOTE: inside SECURITY DEFINER functions current_user is the owner, so
-- it must not be used for this check; we look at the caller's JWT / session instead.
create or replace function private.is_trusted_backend()
returns boolean
language sql stable set search_path = public
as $$
  select coalesce((
         coalesce(
           nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
           nullif(current_setting('request.jwt.claim.role', true), '')
         ) = 'service_role'
      or (auth.uid() is null
          and session_user <> 'authenticator'
          and coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
                       nullif(current_setting('request.jwt.claim.role', true), ''), '') = '')
  ), false)
$$;

create or replace function public.restore_backup(
  p_backup jsonb, p_mode text default 'merge', p_dry_run boolean default true, p_confirm text default null
)
returns jsonb
language plpgsql security definer set search_path = public, private
as $$
declare
  v_tables text[] := array['rooms', 'pricing_rules', 'addon_presets', 'expenses', 'bookings', 'payments', 'booking_addons', 'audit_logs'];
  v_all text[] := array['rooms', 'pricing_rules', 'addon_presets', 'expenses', 'bookings', 'payments', 'booking_addons', 'audit_logs', 'settings'];
  v_t text;
  v_report jsonb := '{}'::jsonb;
  v_result jsonb;
  v_missing_users jsonb;
  v_actor uuid := auth.uid();
  v_actor_name text;
begin
  if not coalesce(public.is_admin() or private.is_trusted_backend(), false) then
    raise exception 'Only admins can restore backups';
  end if;
  if p_mode not in ('merge', 'replace') then
    raise exception 'Mode must be merge or replace';
  end if;
  if coalesce(p_backup ->> 'format', '') <> 'tranquil-rest-backup/1' then
    raise exception 'This is not a Tranquil Rest backup file';
  end if;
  if p_mode = 'replace' and not p_dry_run and coalesce(p_confirm, '') <> 'REPLACE ALL DATA' then
    raise exception 'Replace needs the confirmation text REPLACE ALL DATA';
  end if;
  select display_name into v_actor_name from public.profiles where id = v_actor;

  begin
    -- Restored rows must keep their original timestamps/authors and must not
    -- spam the audit log, so user triggers are paused (transactionally).
    foreach v_t in array v_all loop
      execute format('alter table public.%I disable trigger user', v_t);
    end loop;

    if p_mode = 'replace' then
      delete from public.booking_addons;
      delete from public.payments;
      delete from public.bookings;
      delete from public.expenses;
      delete from public.audit_logs;
      delete from public.pricing_rules;
      delete from public.addon_presets;
      delete from public.rooms;
    end if;

    foreach v_t in array v_tables loop
      v_report := v_report || jsonb_build_object(v_t, private.restore_table(v_t, p_backup -> v_t, p_mode));
    end loop;

    -- Settings: single row. Replace overwrites it; merge leaves current settings alone.
    if p_mode = 'replace' and p_backup ? 'settings' and jsonb_typeof(p_backup -> 'settings') = 'object' then
      update public.settings s set
        property_name           = coalesce(p_backup -> 'settings' ->> 'property_name', s.property_name),
        property_phone          = p_backup -> 'settings' ->> 'property_phone',
        cleaning_buffer_minutes = coalesce((p_backup -> 'settings' ->> 'cleaning_buffer_minutes')::int, s.cleaning_buffer_minutes)
      where id = 1;
      v_report := v_report || jsonb_build_object('settings', jsonb_build_object('restored', 1, 'skipped', 0));
    end if;

    -- Staff roles/names: only for accounts that exist in this project.
    if p_mode = 'replace' then
      update public.profiles p set role = (b ->> 'role')::public.app_role, display_name = b ->> 'display_name', active = (b ->> 'active')::boolean
      from jsonb_array_elements(coalesce(p_backup -> 'profiles', '[]')) b
      where p.id = (b ->> 'id')::uuid and p.id is distinct from v_actor; -- never demote the person restoring
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('id', b ->> 'id', 'display_name', b ->> 'display_name', 'role', b ->> 'role')), '[]')
      into v_missing_users
    from jsonb_array_elements(coalesce(p_backup -> 'profiles', '[]')) b
    where not exists (select 1 from auth.users u where u.id = (b ->> 'id')::uuid);

    -- Keep identity counters ahead of restored IDs.
    perform setval(pg_get_serial_sequence('public.audit_logs', 'id'), greatest((select max(id) from public.audit_logs), 1));

    foreach v_t in array v_all loop
      execute format('alter table public.%I enable trigger user', v_t);
    end loop;

    v_result := jsonb_build_object(
      'mode', p_mode,
      'dry_run', p_dry_run,
      'backup_exported_at', p_backup ->> 'exported_at',
      'tables', v_report,
      'missing_users', v_missing_users
    );

    insert into public.audit_logs (table_name, action, actor_id, actor_name, new_data)
    values ('backup', 'restore_' || p_mode, v_actor, coalesce(v_actor_name, current_user), v_result);

    if p_dry_run then
      raise exception using errcode = 'P0D01', message = v_result::text;
    end if;
  exception when sqlstate 'P0D01' then
    -- Dry run: everything above is rolled back, report returned.
    return sqlerrm::jsonb;
  end;

  return v_result;
end $$;

revoke execute on function private.snapshot(), private.restore_table(text, jsonb, text), private.is_trusted_backend() from public, anon, authenticated;
revoke execute on function public.restore_backup(jsonb, text, boolean, text), public.export_backup_admin() from public, anon;
grant execute on function public.restore_backup(jsonb, text, boolean, text), public.export_backup_admin() to authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.restore_backup(jsonb, text, boolean, text), public.export_backup_admin() to service_role;
  end if;
end $$;

-- Fix: settings.id is a smallint, not a uuid, so the audit trigger failed on every
-- settings update. Only treat the id as a record_id when it is a uuid.
create or replace function public.tg_audit()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_action text := lower(tg_op);
  v_raw    text;
  v_id     uuid;
  v_name   text;
begin
  if tg_op = 'UPDATE' and tg_table_name = 'bookings' then
    if (to_jsonb(new) ->> 'status') is distinct from (to_jsonb(old) ->> 'status') then
      v_action := case to_jsonb(new) ->> 'status'
        when 'cancelled'   then 'cancel'
        when 'checked_in'  then 'check_in'
        when 'checked_out' then 'check_out'
        else 'update' end;
    end if;
  end if;

  v_raw := case when tg_op = 'DELETE' then to_jsonb(old) ->> 'id' else to_jsonb(new) ->> 'id' end;
  if v_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_id := v_raw::uuid;
  end if;
  select display_name into v_name from public.profiles where id = auth.uid();

  insert into public.audit_logs (table_name, record_id, action, actor_id, actor_name, old_data, new_data)
  values (
    tg_table_name, v_id, v_action, auth.uid(), coalesce(v_name, 'system'),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end
  );
  return coalesce(new, old);
end $$;

-- ============================================================================
-- 20261123000005_audit_staff.sql
-- ============================================================================
-- Audit staff account changes (added, renamed, role changed, (de)activated, PIN set).
-- The PIN hash itself is never copied into the audit log; a PIN change is recorded
-- as "pin_changed": true.

create or replace function public.tg_audit()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_action text := lower(tg_op);
  v_old    jsonb := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) - 'pin_hash' end;
  v_new    jsonb := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) - 'pin_hash' end;
  v_raw    text;
  v_id     uuid;
  v_name   text;
begin
  if tg_op = 'UPDATE' and tg_table_name = 'bookings' then
    if (v_new ->> 'status') is distinct from (v_old ->> 'status') then
      v_action := case v_new ->> 'status'
        when 'cancelled'   then 'cancel'
        when 'checked_in'  then 'check_in'
        when 'checked_out' then 'check_out'
        else 'update' end;
    end if;
  end if;

  if tg_table_name = 'profiles' and tg_op = 'UPDATE' then
    if (to_jsonb(new) ->> 'pin_hash') is distinct from (to_jsonb(old) ->> 'pin_hash') then
      v_new := v_new || '{"pin_changed": true}';
      v_old := v_old || '{"pin_changed": false}';
    end if;
    if v_new = v_old then
      return new; -- nothing visible changed
    end if;
  end if;

  v_raw := coalesce(v_new, v_old) ->> 'id';
  if v_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_id := v_raw::uuid;
  end if;
  select display_name into v_name from public.profiles where id = auth.uid();

  insert into public.audit_logs (table_name, record_id, action, actor_id, actor_name, old_data, new_data)
  values (tg_table_name, v_id, v_action, auth.uid(), coalesce(v_name, 'system'), v_old, v_new);
  return coalesce(new, old);
end $$;

drop trigger if exists audit_profiles on public.profiles;
create trigger audit_profiles after insert or update or delete on public.profiles
  for each row execute function public.tg_audit();

-- ============================================================================
-- 20261123000006_new_accounts_inactive.sql
-- ============================================================================
-- Defence in depth: a brand-new auth account has NO access until an admin activates it.
-- (Public sign-ups are also disabled in the project's auth settings; this protects the
-- data even if that setting is ever switched back on.)
-- Staff created through Admin → Settings → Add staff member are activated by the
-- staff-admin function; the owner account is activated by the SQL in the README.

alter table public.profiles alter column active set default false;

create or replace function public.handle_new_user()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  insert into public.profiles (id, display_name, active)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1)), false)
  on conflict (id) do nothing;
  return new;
end $$;

